const marked={parse:function(src){if(!src)return'';let h=src.replace(/&(?!amp;|lt;|gt;|quot;)/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');h=h.replace(/```(\w*)\n?([\s\S]*?)```/g,(_,l,c)=>`<pre><code class="lang-${l||''}">${c.trim()}</code></pre>`);h=h.replace(/`([^`]+)`/g,'<code>$1</code>');h=h.replace(/^#### (.+)$/gm,'<h4>$1</h4>');h=h.replace(/^### (.+)$/gm,'<h3>$1</h3>');h=h.replace(/^## (.+)$/gm,'<h2>$1</h2>');h=h.replace(/^# (.+)$/gm,'<h1>$1</h1>');h=h.replace(/\*\*\*(.+?)\*\*\*/g,'<strong><em>$1</em></strong>');h=h.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');h=h.replace(/\*(.+?)\*/g,'<em>$1</em>');h=h.replace(/^[-*] (.+)$/gm,'<li>$1</li>');h=h.replace(/^\d+\. (.+)$/gm,'<oli>$1</oli>');h=h.replace(/^---$/gm,'<hr>');h=h.replace(/^&gt; (.+)$/gm,'<blockquote>$1</blockquote>');h=h.replace(/\[([^\]]+)\]\(([^)]+)\)/g,'<a href="$2" target="_blank">$1</a>');const blocks=h.split(/\n\n+/);h=blocks.map(b=>{b=b.trim();if(!b)return'';if(/^<(h[1-6]|pre|blockquote|hr|ul|ol)/.test(b))return b;if(b.includes('<li>')){return'<ul>'+b+'</ul>';}if(b.includes('<oli>')){return'<ol>'+b.replace(/<\/?oli>/g,m=>m==='<oli>'?'<li>':'</li>')+'</ol>';}return'<p>'+b.replace(/\n/g,'<br>')+'</p>';}).join('');return h;}};
